const out=[]; const seen=new Set();
for(const i of items){for(const r of (i.json.results||[])){try{const u=new URL(r.url);u.hash='';['utm_source','utm_medium','utm_campaign'].forEach(k=>u.searchParams.delete(k));const url=u.href;if(seen.has(url))continue;seen.add(url);out.push({json:{canonical_url:url,discovery_title:r.title||'',discovery_snippet:r.content||'',source_class:/oumeng\.com\.cn$/i.test(u.hostname)?'primary_official':/(nmpa|samr|gov)\.gov\.cn$/i.test(u.hostname)?'primary_regulatory':'secondary'}});}catch{}}}
// Always seed the official Oumeng news page.
const seed='https://oumeng.com.cn/frontend/news'; if(!seen.has(seed))out.unshift({json:{canonical_url:seed,discovery_title:'Oumeng News',source_class:'primary_official'}}); return out;
